from scipy.optimize import least_squares
y=dP_dt
def fit(f,x0,n=8):
    best=None
    rng=np.random.default_rng(0)
    for s in range(n):
        x=np.array(x0,float)*(1+0.5*rng.standard_normal(len(x0))) if s else np.array(x0,float)
