import numpy as np
from scipy.optimize import least_squares
y=dP_dt
def fit(f,x0,n=10):
    best=None; rng=np.random.default_rng(1)
    for s in range(n):
        x=np.array(x0,float)*(1+0.4*rng.standard_normal(len(x0))) if s else np.array(x0,float)
        try:
            r=least_squares(lambda q: np.nan_to_num(f(q)-y,nan=1e3), x, max_nfev=4000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    return np.mean((y-f(best.x))**2)/np.var(y), np.round(best.x,4)
